import Foundation

/// The game rules. A faithful port of the engine in the web app's index.html,
/// which stays the source of truth: `Tests/GyattCoreTests/Fixtures` holds
/// answers generated by the web engine, and the tests replay them here.
///
/// Everything takes `now` explicitly so the rules are deterministic and
/// testable; the calendar decides what "a day" means (the user's local day).
public struct Engine: Sendable {
    /// Minutes of chores on a full daily card.
    public static let dailyMinutes = 25
    /// A card this long already counts as a full day and can be locked in.
    public static let fullDayMinutes = dailyMinutes - 5
    /// Days shown in the home-screen daily log.
    public static let logDays = 30
    /// `neglectDays` for a chore the player has never had approved.
    public static let neverDone = 999

    public let pool: [Chore]
    public var calendar: Calendar
    private let poolById: [String: Chore]

    public init(pool: [Chore] = ChoreCatalog.pool, calendar: Calendar = .current) {
        self.pool = pool
        self.calendar = calendar
        self.poolById = Dictionary(pool.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
    }

    // MARK: - Escalation

    /// Whole 24-hour periods since this player last had the chore approved.
    public func neglectDays(choreId: String, playerId: String, logs: [ChoreLog], now: Date) -> Int {
        var last: Date?
        for log in logs where log.playerId == playerId && log.choreId == choreId && log.status == .approved {
            if let current = last, current >= log.timestamp { continue }
            last = log.timestamp
        }
        guard let last else { return Self.neverDone }
        // Integer milliseconds, like the web app, so day boundaries are exact.
        let elapsed = Self.milliseconds(now) - Self.milliseconds(last)
        return Int((Double(elapsed) / 86_400_000).rounded(.down))
    }

    /// Resolve a chore's current escalation tier from how long it's been neglected.
    public func enrich(_ chore: Chore, neglectDays days: Int) -> CardChore {
        var tier = 0
        for i in chore.tierDays.indices.reversed() where days >= chore.tierDays[i] {
            tier = i
            break
        }
        return CardChore(
            id: chore.id, name: chore.name, cat: chore.cat, pts: chore.pts,
            neglectDays: days, currentMinutes: chore.tiers[tier], escalLevel: tier
        )
    }

    /// The pool as this player sees it right now, most neglected first (then
    /// shortest first), so overdue chores surface as suggestions.
    public func pickableChores(playerId: String, logs: [ChoreLog], now: Date) -> [CardChore] {
        pool
            .map { enrich($0, neglectDays: neglectDays(choreId: $0.id, playerId: playerId, logs: logs, now: now)) }
            .stableSorted { a, b in
                if a.neglectDays != b.neglectDays { return a.neglectDays > b.neglectDays }
                return a.currentMinutes < b.currentMinutes
            }
    }

    // MARK: - Building a card

    /// Top a selection up to the budget with chores that make sense: the same
    /// area as what's already picked first, then the most neglected.
    public func suggestFill(picked: [String], pool: [CardChore], cap: Int = Engine.dailyMinutes) -> [String] {
        let pickedSet = Set(picked)
        let chosen = pool.filter { pickedSet.contains($0.id) }
        let cats = Set(chosen.map(\.cat))
        var total = chosen.reduce(0) { $0 + $1.currentMinutes }
        var result = picked

        let candidates = pool
            .filter { !pickedSet.contains($0.id) }
            .stableSorted { a, b in
                let aSame = cats.contains(a.cat), bSame = cats.contains(b.cat)
                if aSame != bSame { return aSame }
                if a.neglectDays != b.neglectDays { return a.neglectDays > b.neglectDays }
                return a.currentMinutes > b.currentMinutes
            }
        for chore in candidates where total + chore.currentMinutes <= cap {
            result.append(chore.id)
            total += chore.currentMinutes
        }
        return result
    }

    /// Where a selection stands against the daily budget. In the bonus round
    /// there's no cap: anything picked is ready to log.
    public func pickerSummary(picked: Set<String>, pool: [CardChore], bonus: Bool) -> PickerSummary {
        let chosen = pool.filter { picked.contains($0.id) }
        let total = chosen.reduce(0) { $0 + $1.currentMinutes }
        let remaining = bonus ? nil : Self.dailyMinutes - total
        let shortestUnpicked = pool.filter { !picked.contains($0.id) }.map(\.currentMinutes).min()

        var canAddMore = false
        if let remaining, let shortestUnpicked { canAddMore = shortestUnpicked <= remaining }
        let isFull = total >= Self.fullDayMinutes
        let isReady = !chosen.isEmpty && (bonus || isFull || !canAddMore)
        return PickerSummary(total: total, remaining: remaining, canAddMore: canAddMore, isFull: isFull, isReady: isReady)
    }

    /// The pending logs a submitted set of chores turns into. Timestamps step by
    /// a millisecond so the submitted order survives sorting.
    public func makeLogs(for chores: [CardChore], player: Player, now: Date) -> [ChoreLog] {
        chores.enumerated().map { index, chore in
            ChoreLog(
                playerId: player.id, playerName: player.name,
                choreId: chore.id, choreName: chore.name,
                points: chore.pts, minutes: chore.currentMinutes,
                timestamp: now.addingTimeInterval(Double(index) / 1000),
                status: .pending
            )
        }
    }

    // MARK: - Today

    /// Rebuild today's already-submitted card from the logs alone — what a device
    /// that didn't build the card (a parent's phone, a reinstall) should show.
    public func cardFromLogs(playerId: String, logs: [ChoreLog], now: Date) -> DailyCard? {
        var seen = Set<String>()
        var chores: [CardChore] = []
        for log in logs where log.playerId == playerId && calendar.isDate(log.timestamp, inSameDayAs: now) {
            guard seen.insert(log.choreId).inserted else { continue }
            chores.append(cardChore(for: log, playerId: playerId, logs: logs, now: now))
        }
        guard !chores.isEmpty else { return nil }
        return DailyCard(chores: chores, checked: chores.map { _ in true }, submitted: true)
    }

    /// The parent's verdict per chore today, plus whatever was logged in the
    /// bonus round (today's logs that aren't on the card).
    public func todayState(playerId: String, logs: [ChoreLog], card: DailyCard, now: Date) -> TodayState {
        let todays = logs.filter { $0.playerId == playerId && calendar.isDate($0.timestamp, inSameDayAs: now) }

        // Approved / rejected win over pending if a chore has more than one row.
        func weight(_ status: LogStatus) -> Int {
            switch status {
            case .approved: return 3
            case .rejected: return 2
            case .pending: return 1
            }
        }
        var statusByChore: [String: LogStatus] = [:]
        for log in todays {
            if let current = statusByChore[log.choreId], weight(current) >= weight(log.status) { continue }
            statusByChore[log.choreId] = log.status
        }

        let cardIds = Set(card.chores.map(\.id))
        var seen = Set<String>()
        var bonus: [CardChore] = []
        for log in todays where !cardIds.contains(log.choreId) {
            guard seen.insert(log.choreId).inserted else { continue }
            bonus.append(cardChore(for: log, playerId: playerId, logs: logs, now: now))
        }

        // A chore can be logged once per day, on the card or in the bonus round.
        let loggedToday = cardIds.union(bonus.map(\.id))
        let bonusLeft = pool.filter { !loggedToday.contains($0.id) }.count
        return TodayState(statusByChore: statusByChore, bonus: bonus, loggedToday: loggedToday, bonusLeft: bonusLeft)
    }

    private func cardChore(for log: ChoreLog, playerId: String, logs: [ChoreLog], now: Date) -> CardChore {
        if let base = poolById[log.choreId] {
            return enrich(base, neglectDays: neglectDays(choreId: base.id, playerId: playerId, logs: logs, now: now))
        }
        // A chore that's since left the pool: show what the log recorded.
        return CardChore(id: log.choreId, name: log.choreName, cat: "", pts: log.points,
                         neglectDays: 0, currentMinutes: 0, escalLevel: 0)
    }

    // MARK: - XP, level, streak

    /// Streak multiplier — a day's chores are worth more the longer the run, up to 2x.
    public static func momentumMult(streak: Int) -> Double {
        1 + Double(min(streak, 10)) * 0.1
    }

    /// XP needed to go from `level` to `level + 1`.
    public static func xpToNext(level: Int) -> Int {
        60 + (level - 1) * 20
    }

    /// Levels are framed as version numbers: v1.0 → v1.1 → … → v2.0.
    public static func version(level: Int) -> String {
        "v\((level - 1) / 10 + 1).\((level - 1) % 10)"
    }

    public static func rank(xp: Int) -> Rank {
        var level = 1
        var into = xp
        while into >= xpToNext(level: level) {
            into -= xpToNext(level: level)
            level += 1
        }
        let need = xpToNext(level: level)
        return Rank(
            level: level, version: version(level: level), nextVersion: version(level: level + 1),
            into: into, need: need, pct: Int((Double(into) / Double(need) * 100).rounded())
        )
    }

    /// Approved logs for a player, one per chore per local day. The game allows
    /// a chore once a day, so extra rows are sync duplicates and must not bank
    /// XP or minutes twice. The first row in `logs` order wins.
    func approvedOncePerDay(playerId: String, logs: [ChoreLog]) -> [(day: Date, log: ChoreLog)] {
        struct Key: Hashable {
            let day: Date
            let choreId: String
        }
        var seen = Set<Key>()
        var out: [(day: Date, log: ChoreLog)] = []
        for log in logs where log.playerId == playerId && log.status == .approved {
            let day = calendar.startOfDay(for: log.timestamp)
            guard seen.insert(Key(day: day, choreId: log.choreId)).inserted else { continue }
            out.append((day, log))
        }
        return out
    }

    /// Lifetime XP. Each day's approved points are scaled by that day's running
    /// streak multiplier. XP only ever grows; a broken streak just resets the multiplier.
    public func xp(playerId: String, logs: [ChoreLog]) -> Int {
        var byDay: [Date: Int] = [:]
        for entry in approvedOncePerDay(playerId: playerId, logs: logs) {
            byDay[entry.day, default: 0] += entry.log.points
        }
        var xp = 0
        var run = 0
        var previous: Date?
        for day in byDay.keys.sorted() {
            if let previous, calendar.date(byAdding: .day, value: 1, to: previous) == day {
                run += 1
            } else {
                run = 1
            }
            // The first day of a run earns 1x.
            xp += Int((Double(byDay[day] ?? 0) * Self.momentumMult(streak: run - 1)).rounded())
            previous = day
        }
        return xp
    }

    /// Consecutive days, counting back from today, with at least one approved chore.
    public func streak(playerId: String, logs: [ChoreLog], now: Date) -> Int {
        let approvedDays = Set(
            logs.filter { $0.playerId == playerId && $0.status == .approved }
                .map { calendar.startOfDay(for: $0.timestamp) }
        )
        var streak = 0
        var day = calendar.startOfDay(for: now)
        while streak < 365, approvedDays.contains(day) {
            streak += 1
            guard let earlier = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = earlier
        }
        return streak
    }

    // MARK: - Daily 25-minute log

    /// Minutes a log contributed to its day. New logs record the exact minutes;
    /// rows without them fall back to the chore's base tier, then to its points.
    public func choreMinutes(_ log: ChoreLog) -> Int {
        if let minutes = log.minutes { return minutes }
        if let chore = poolById[log.choreId] { return chore.tiers[0] }
        return log.points
    }

    /// Approved minutes per local day, keyed by the day's start.
    public func minutesByDay(playerId: String, logs: [ChoreLog]) -> [Date: Int] {
        var byDay: [Date: Int] = [:]
        for entry in approvedOncePerDay(playerId: playerId, logs: logs) {
            byDay[entry.day, default: 0] += choreMinutes(entry.log)
        }
        return byDay
    }

    /// The last `logDays` day-starts, oldest first, today last.
    public func recentDays(now: Date) -> [Date] {
        let today = calendar.startOfDay(for: now)
        return (0..<Self.logDays).reversed().compactMap {
            calendar.date(byAdding: .day, value: -$0, to: today)
        }
    }

    /// One player's row of the home-screen log: minutes per day, and how many
    /// days cleared the 25-minute goal.
    public func dailyLog(playerId: String, logs: [ChoreLog], now: Date) -> DailyLogRow {
        let byDay = minutesByDay(playerId: playerId, logs: logs)
        let days = recentDays(now: now).map { DayMinutes(date: $0, minutes: byDay[$0] ?? 0) }
        let hits = days.filter(\.isHit).count
        let pct = Int((Double(hits) / Double(Self.logDays) * 100).rounded())
        return DailyLogRow(days: days, hits: hits, pct: pct)
    }

    // MARK: - Helpers

    private static func milliseconds(_ date: Date) -> Int64 {
        Int64((date.timeIntervalSince1970 * 1000).rounded())
    }
}

extension Array {
    /// `sorted(by:)` makes no stability promise; the web app's rules rely on a
    /// stable sort (ties keep pool order), so ties fall back to original position.
    func stableSorted(by areInIncreasingOrder: (Element, Element) -> Bool) -> [Element] {
        enumerated()
            .sorted { a, b in
                if areInIncreasingOrder(a.element, b.element) { return true }
                if areInIncreasingOrder(b.element, a.element) { return false }
                return a.offset < b.offset
            }
            .map(\.element)
    }
}
